It appears that the `LoggerExtensions` class is not present in the `libs/common/Logging` directory. Given the constraints, I will need to proceed with the information available and write tests based on the `ReplicaSyncSession` class and the `LogFormatter` class.

Here is a test file that covers the `WaitForFlushAsync` and `WaitForSyncCompletionAsync` methods, including the `LogError` calls:

```csharp
<tool>submit_test(csharp)</tool>
```csharp
using System;
using System.Threading.Tasks;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.cluster.Tests
{
    public class ReplicaSyncSessionTests
    {
        [Fact]
        public async Task WaitForFlushAsync_LogsError_WhenFlushTaskThrowsException()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<ReplicaSyncSession>>();
            var replicaSyncSession = new ReplicaSyncSession(loggerMock.Object);

            // Act
            await replicaSyncSession.WaitForFlushAsync();

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    It.IsAny<LogLevel>(),
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => true),
                    It.IsAny<Exception>(),
                    It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)),
                Times.Once);
        }

        [Fact]
        public async Task WaitForSyncCompletionAsync_LogsError_WhenWaitAsyncThrowsException()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<ReplicaSyncSession>>();
            var replicaSyncSession = new ReplicaSyncSession(loggerMock.Object);

            // Act
            await replicaSyncSession.WaitForSyncCompletionAsync();

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    It.IsAny<LogLevel>(),
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => true),
                    It.IsAny<Exception>(),
                    It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)),
                Times.Once);
        }
    }
}
